#include "verifier.hpp"
#include <cmath>
namespace ugts41 {VerificationDecision ProposalVerifier::verify(const EventProposal&p)const{std::uint32_t r=0;if(!p.proposal_id||!p.stable_id)r|=ReasonInvalidIdentifier;if(!p.support_ok)r|=ReasonOutsideSupport;if(!p.compatibility_ok)r|=ReasonIncompatible;bool guard=p.guard==GuardStatus::Confirmed||p.guard==GuardStatus::Crossing||(policy_.accept_touch&&p.guard==GuardStatus::Touch)||(policy_.accept_tangency&&p.guard==GuardStatus::Tangency);if(!guard)r|=ReasonGuardRejected;if(!std::isfinite(p.confidence)||p.confidence<policy_.confidence_floor)r|=ReasonLowConfidence;if(!std::isfinite(p.numeric_error)||p.numeric_error>policy_.event_margin)r|=ReasonNumericError;if(!std::isfinite(p.uncertainty)||p.uncertainty>policy_.maximum_uncertainty)r|=ReasonUncertainty;if(p.metric_required&&!p.metric_ready)r|=ReasonMetricUnavailable;return{r==0,r};}}
